INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-routine-a2-01-01', 'lesson-routine-a2-01', 1, 'sentence', 'My alarm goes off at six.', 'Meu despertador toca às seis.', '/maɪ əˈlɑːrm ɡoʊz ɔːf æt sɪks/', '"Go off" = tocar (alarme). Presente simples para rotina.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"alarm","pos":"noun","ipa":"/əˈlɑːrm/","gloss":"despertador, alarme"},{"surface":"goes","pos":"verb","ipa":"/ɡoʊz/","gloss":"vai"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-02', 'lesson-routine-a2-01', 2, 'sentence', 'I usually hit the snooze button.', 'Eu geralmente aperto o soneca.', '/aɪ ˈjuːʒuəli hɪt ðə snuːz ˈbʌtən/', '"Snooze" = função soneca. "Usually" vai antes do verbo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"hit","pos":"verb","ipa":"/hɪt/","gloss":"bater, pegar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"snooze","pos":"noun","ipa":"/snuːz/","gloss":"soneca"},{"surface":"button","pos":"noun","ipa":"/ˈbʌtən/","gloss":"botão"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-03', 'lesson-routine-a2-01', 3, 'sentence', 'I brush my teeth and take a shower.', 'Escovo os dentes e tomo banho.', '/aɪ brʌʃ maɪ tiːθ ænd teɪk ə ˈʃaʊər/', 'Possessivo com partes do corpo: "my teeth". "Take a shower" = tomar banho.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"brush","pos":"verb","ipa":"/brʌʃ/","gloss":"escovar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"teeth","pos":"noun","ipa":"/tiːθ/","gloss":"dentes"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"shower","pos":"noun","ipa":"/ˈʃaʊər/","gloss":"banho de chuveiro"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-04', 'lesson-routine-a2-01', 4, 'sentence', 'I''m getting dressed.', 'Estou me vestindo.', '/aɪm ˈɡɛtɪŋ drɛst/', 'Presente contínuo para o que está acontecendo agora. "Get dressed" = vestir-se.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"getting","pos":"verb","ipa":"/ˈɡɛtɪŋ/","gloss":"ficando; getting up = levantar-se"},{"surface":"dressed","pos":"adjective","ipa":"/drɛst/","gloss":"vestido (get dressed = vestir-se)"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-05', 'lesson-routine-a2-01', 5, 'sentence', 'I make my bed every morning.', 'Arrumo a cama toda manhã.', '/aɪ meɪk maɪ bɛd ˈɛvri ˈmɔːrnɪŋ/', '"Make the bed" = arrumar a cama (não "arrange").', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bed","pos":"noun","ipa":"/bɛd/","gloss":"cama"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-06', 'lesson-routine-a2-01', 6, 'sentence', 'She puts on makeup before work.', 'Ela se maquia antes do trabalho.', '/ʃiː pʊts ɑːn ˈmeɪkʌp bɪˈfɔːr wɜːrk/', '"Put on makeup" = passar maquiagem.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"puts","pos":"verb","ipa":"/pʊts/","gloss":"coloca"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"makeup","pos":"noun","ipa":"/ˈmeɪkʌp/","gloss":"maquiagem"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-07', 'lesson-routine-a2-01', 7, 'sentence', 'I have coffee and toast for breakfast.', 'Tomo café com torrada no café da manhã.', '/aɪ hæv ˈkɔːfi ænd toʊst fɔːr ˈbrɛkfəst/', '"Have" + comida = comer/beber. "For breakfast" = no café da manhã.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"toast","pos":"noun","ipa":"/toʊst/","gloss":"torrada"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-08', 'lesson-routine-a2-01', 8, 'sentence', 'I''m running late!', 'Estou atrasado!', '/aɪm ˈrʌnɪŋ leɪt/', 'Presente contínuo: "running late" = atrasado agora.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"running","pos":"verb","ipa":"/ˈrʌnɪŋ/","gloss":"ficando (running late)"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-09', 'lesson-routine-a2-01', 9, 'sentence', 'Don''t forget your keys.', 'Não esqueça as chaves.', '/doʊnt fərˈɡɛt jʊr kiːz/', 'Imperativo negativo.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"forget","pos":"verb","ipa":"/fərˈɡɛt/","gloss":"esquecer"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-01-10', 'lesson-routine-a2-01', 10, 'sentence', 'I leave home at seven thirty.', 'Saio de casa às sete e meia.', '/aɪ liːv hoʊm æt ˈsɛvən ˈθɜːrti/', '"Leave home" sem "the". Horário: "seven thirty".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"},{"surface":"thirty","pos":"numeral","ipa":"/ˈθɜːrti/","gloss":"trinta"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-routine-a2-02-01', 'lesson-routine-a2-02', 1, 'sentence', 'I do the laundry on Saturdays.', 'Lavo roupa aos sábados.', '/aɪ duː ðə ˈlɔːndri ɑːn ˈsætərdeɪz/', '"Do the laundry" = lavar roupa. Tarefas usam "do".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"laundry","pos":"noun","ipa":"/ˈlɔːndri/","gloss":"lavanderia"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Saturdays","pos":"proper noun","ipa":"/ˈsætərdeɪz/","gloss":"sábados"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-02', 'lesson-routine-a2-02', 2, 'sentence', 'Can you take out the trash?', 'Pode levar o lixo para fora?', '/kæn juː teɪk aʊt ðə træʃ/', '"Take out" = levar para fora. Pedido com "can".', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"trash","pos":"noun","ipa":"/træʃ/","gloss":"lixo"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-03', 'lesson-routine-a2-02', 3, 'sentence', 'It''s your turn to do the dishes.', 'É a sua vez de lavar a louça.', '/ɪts jʊr tɜːrn tuː duː ðə ˈdɪʃɪz/', '"It''s your turn to" = é a sua vez de.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dishes","pos":"noun","ipa":"/ˈdɪʃɪz/","gloss":"louça, pratos"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-04', 'lesson-routine-a2-02', 4, 'sentence', 'I need to vacuum the living room.', 'Preciso passar o aspirador na sala.', '/aɪ niːd tuː ˈvækjuːm ðə ˈlɪvɪŋ ruːm/', '"Vacuum" = aspirar. Grafia com dois "u".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"vacuum","pos":"verb","ipa":"/ˈvækjuːm/","gloss":"aspirar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"living","pos":"adjective","ipa":"/ˈlɪvɪŋ/","gloss":"de estar"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-05', 'lesson-routine-a2-02', 5, 'sentence', 'He is cleaning the bathroom now.', 'Ele está limpando o banheiro agora.', '/hiː ɪz ˈkliːnɪŋ ðə ˈbæθruːm naʊ/', 'Presente contínuo + "now".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"cleaning","pos":"verb","ipa":"/ˈkliːnɪŋ/","gloss":"limpando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bathroom","pos":"noun","ipa":"/ˈbæθruːm/","gloss":"banheiro"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-06', 'lesson-routine-a2-02', 6, 'sentence', 'Who fed the cat?', 'Quem deu comida para o gato?', '/huː fɛd ðə kæt/', '"Fed" = passado de "feed" (alimentar). Pergunta com "who" sem "did".', '[]'::jsonb, '[{"surface":"Who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"fed","pos":"verb","ipa":"/fɛd/","gloss":"alimentou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cat","pos":"noun","ipa":"/kæt/","gloss":"gato"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-07', 'lesson-routine-a2-02', 7, 'sentence', 'I''ll water the plants.', 'Eu rego as plantas.', '/aɪl ˈwɔːtər ðə plænts/', '"Water" como verbo = regar. "Will" para oferta na hora.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plants","pos":"noun","ipa":"/plænts/","gloss":"plantas"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-08', 'lesson-routine-a2-02', 8, 'sentence', 'The house is a mess.', 'A casa está uma bagunça.', '/ðə haʊs ɪz ə mɛs/', '"Mess" = bagunça. "Messy" = bagunçado.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"house","pos":"noun","ipa":"/haʊs/","gloss":"casa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"mess","pos":"noun","ipa":"/mɛs/","gloss":"bagunça"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-09', 'lesson-routine-a2-02', 9, 'sentence', 'Let''s clean up before they arrive.', 'Vamos arrumar antes que eles cheguem.', '/lɛts kliːn ʌp bɪˈfɔːr ðeɪ əˈraɪv/', '"Clean up" = arrumar, limpar tudo. Depois de "before", presente.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"clean","pos":"verb","ipa":"/kliːn/","gloss":"limpar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-02-10', 'lesson-routine-a2-02', 10, 'sentence', 'I hate ironing.', 'Odeio passar roupa.', '/aɪ heɪt ˈaɪərnɪŋ/', '"Iron" = ferro de passar; o "r" quase some: /ˈaɪərnɪŋ/.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"hate","pos":"verb","ipa":"/heɪt/","gloss":"odiar"},{"surface":"ironing","pos":"noun","ipa":"/ˈaɪərnɪŋ/","gloss":"passar roupa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-routine-a2-03-01', 'lesson-routine-a2-03', 1, 'sentence', 'What''s for dinner?', 'O que tem para o jantar?', '/wʌts fɔːr ˈdɪnər/', 'Pergunta clássica em casa.', '[]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-02', 'lesson-routine-a2-03', 2, 'sentence', 'I''m making pasta tonight.', 'Vou fazer macarrão hoje à noite.', '/aɪm ˈmeɪkɪŋ ˈpɑːstə təˈnaɪt/', 'Presente contínuo para plano próximo e combinado.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"making","pos":"verb","ipa":"/ˈmeɪkɪŋ/","gloss":"fazendo"},{"surface":"pasta","pos":"noun","ipa":"/ˈpɑːstə/","gloss":"massa"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-03', 'lesson-routine-a2-03', 3, 'sentence', 'Can you set the table?', 'Pode pôr a mesa?', '/kæn juː sɛt ðə ˈteɪbəl/', '"Set the table" = pôr a mesa.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"table","pos":"noun","ipa":"/ˈteɪbəl/","gloss":"mesa"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-04', 'lesson-routine-a2-03', 4, 'sentence', 'Cut the onions into small pieces.', 'Corte as cebolas em pedaços pequenos.', '/kʌt ðə ˈʌnjənz ˈɪntuː smɔːl ˈpiːsɪz/', 'Imperativo de receita. "Into" = em (resultado).', '[]'::jsonb, '[{"surface":"Cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"onions","pos":"noun","ipa":"/ˈʌnjənz/","gloss":"cebolas"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"pieces","pos":"noun","ipa":"/ˈpiːsɪz/","gloss":"pedaços"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-05', 'lesson-routine-a2-03', 5, 'sentence', 'Boil the water first.', 'Ferva a água primeiro.', '/bɔɪl ðə ˈwɔːtər fɜːrst/', '"Boil" = ferver.', '[]'::jsonb, '[{"surface":"Boil","pos":"verb","ipa":"/bɔɪl/","gloss":"ferver"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-06', 'lesson-routine-a2-03', 6, 'sentence', 'The oven is preheating.', 'O forno está preaquecendo.', '/ðə ˈʌvən ɪz ˌpriːˈhiːtɪŋ/', 'Presente contínuo para processo em andamento.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"oven","pos":"noun","ipa":"/ˈʌvən/","gloss":"forno"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"preheating","pos":"verb","ipa":"/ˌpriːˈhiːtɪŋ/","gloss":"preaquecendo"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-07', 'lesson-routine-a2-03', 7, 'sentence', 'It smells delicious.', 'Está com um cheiro delicioso.', '/ɪt smɛlz dɪˈlɪʃəs/', '"Smell" + adjetivo = ter cheiro.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"smells","pos":"verb","ipa":"/smɛlz/","gloss":"cheira"},{"surface":"delicious","pos":"adjective","ipa":"/dɪˈlɪʃəs/","gloss":"delicioso"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-08', 'lesson-routine-a2-03', 8, 'sentence', 'We''re out of eggs.', 'Acabaram os ovos.', '/wɪr aʊt ʌv ɛɡz/', '"Be out of" = estar sem.', '[]'::jsonb, '[{"surface":"We''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"eggs","pos":"noun","ipa":"/ɛɡz/","gloss":"ovos"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-09', 'lesson-routine-a2-03', 9, 'sentence', 'I burned the rice.', 'Queimei o arroz.', '/aɪ bɜːrnd ðə raɪs/', 'Passado regular: "burned" (ou "burnt" no Reino Unido).', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"burned","pos":"verb","ipa":"/bɜːrnd/","gloss":"queimou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"rice","pos":"noun","ipa":"/raɪs/","gloss":"arroz"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-03-10', 'lesson-routine-a2-03', 10, 'sentence', 'Leftovers are in the fridge.', 'As sobras estão na geladeira.', '/ˈlɛftoʊvərz ɑːr ɪn ðə frɪdʒ/', '"Leftovers" = sobras de comida, sempre plural.', '[]'::jsonb, '[{"surface":"Leftovers","pos":"noun","ipa":"/ˈlɛftoʊvərz/","gloss":"sobras"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"fridge","pos":"noun","ipa":"/frɪdʒ/","gloss":"geladeira"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-routine-a2-04-01', 'lesson-routine-a2-04', 1, 'sentence', 'I always drink water in the morning.', 'Sempre bebo água de manhã.', '/aɪ ˈɔːlweɪz drɪŋk ˈwɔːtər ɪn ðə ˈmɔːrnɪŋ/', 'Escala: always (100%), usually, often, sometimes, rarely, never (0%).', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-02', 'lesson-routine-a2-04', 2, 'sentence', 'I often work late.', 'Muitas vezes trabalho até tarde.', '/aɪ ˈɔːfən wɜːrk leɪt/', '"Often" = com frequência; o "t" costuma ser mudo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"often","pos":"adverb","ipa":"/ˈɔːfən/","gloss":"frequentemente"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-03', 'lesson-routine-a2-04', 3, 'sentence', 'She sometimes cooks for her neighbors.', 'Às vezes ela cozinha para os vizinhos.', '/ʃiː ˈsʌmtaɪmz kʊks fɔːr hɜːr ˈneɪbərz/', '"Sometimes" pode ir no começo ou antes do verbo.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"sometimes","pos":"adverb","ipa":"/ˈsʌmtaɪmz/","gloss":"às vezes"},{"surface":"cooks","pos":"verb","ipa":"/kʊks/","gloss":"cozinha"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"neighbors","pos":"noun","ipa":"/ˈneɪbərz/","gloss":"vizinhos"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-04', 'lesson-routine-a2-04', 4, 'sentence', 'We rarely eat out.', 'Raramente comemos fora.', '/wiː ˈrɛrli iːt aʊt/', '"Eat out" = comer fora.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"rarely","pos":"adverb","ipa":"/ˈrɛrli/","gloss":"raramente"},{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-05', 'lesson-routine-a2-04', 5, 'sentence', 'He never skips breakfast.', 'Ele nunca pula o café da manhã.', '/hiː ˈnɛvər skɪps ˈbrɛkfəst/', '"Skip" = pular, deixar de fazer.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"skips","pos":"verb","ipa":"/skɪps/","gloss":"pula"},{"surface":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-06', 'lesson-routine-a2-04', 6, 'sentence', 'How often do you go to the gym?', 'Com que frequência você vai à academia?', '/haʊ ˈɔːfən duː juː ɡoʊ tuː ðə dʒɪm/', '"How often" pergunta frequência.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"often","pos":"adverb","ipa":"/ˈɔːfən/","gloss":"frequentemente"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"gym","pos":"noun","ipa":"/dʒɪm/","gloss":"academia"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-07', 'lesson-routine-a2-04', 7, 'sentence', 'Twice a week.', 'Duas vezes por semana.', '/twaɪs ə wiːk/', '"Once" = uma vez, "twice" = duas vezes, depois "three times".', '[]'::jsonb, '[{"surface":"Twice","pos":"adverb","ipa":"/twaɪs/","gloss":"duas vezes"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-08', 'lesson-routine-a2-04', 8, 'sentence', 'I''m usually in bed by eleven.', 'Geralmente estou na cama às onze.', '/aɪm ˈjuːʒuəli ɪn bɛd baɪ ɪˈlɛvən/', 'Com "to be", o advérbio vem depois do verbo: "I''m usually".', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"bed","pos":"noun","ipa":"/bɛd/","gloss":"cama"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"eleven","pos":"numeral","ipa":"/ɪˈlɛvən/","gloss":"onze"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-09', 'lesson-routine-a2-04', 9, 'sentence', 'I used to smoke, but I quit.', 'Eu fumava, mas parei.', '/aɪ juːzd tuː smoʊk bʌt aɪ kwɪt/', '"Used to" = costumava (hábito do passado que acabou).', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"smoke","pos":"verb","ipa":"/smoʊk/","gloss":"fumar"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"quit","pos":"verb","ipa":"/kwɪt/","gloss":"parar, largar"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-04-10', 'lesson-routine-a2-04', 10, 'sentence', 'I''m trying to sleep more.', 'Estou tentando dormir mais.', '/aɪm ˈtraɪɪŋ tuː sliːp mɔːr/', 'Presente contínuo para mudança em andamento.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"trying","pos":"verb","ipa":"/ˈtraɪɪŋ/","gloss":"tentando"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-routine-a2-05-01', 'lesson-routine-a2-05', 1, 'sentence', 'What did you do last weekend?', 'O que você fez no fim de semana passado?', '/wʌt dɪd juː duː læst ˈwiːkɛnd/', 'Pergunta no passado: "did" + verbo base.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"weekend","pos":"noun","ipa":"/ˈwiːkɛnd/","gloss":"fim de semana"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-02', 'lesson-routine-a2-05', 2, 'sentence', 'I stayed home and relaxed.', 'Fiquei em casa e descansei.', '/aɪ steɪd hoʊm ænd rɪˈlækst/', 'Passados regulares: "stayed", "relaxed".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"stayed","pos":"verb","ipa":"/steɪd/","gloss":"ficou"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"relaxed","pos":"adjective","ipa":"/rɪˈlækst/","gloss":"relaxado"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-03', 'lesson-routine-a2-05', 3, 'sentence', 'We went to my parents'' house.', 'Fomos à casa dos meus pais.', '/wiː wɛnt tuː maɪ ˈpɛrənts haʊs/', '"Parents'' house": apóstrofo depois do "s" no plural.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"went","pos":"verb","ipa":"/wɛnt/","gloss":"foi (passado de go)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"parents''","pos":"noun","ipa":"/ˈpɛrənts/","gloss":"dos pais"},{"surface":"house","pos":"noun","ipa":"/haʊs/","gloss":"casa"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-04', 'lesson-routine-a2-05', 4, 'sentence', 'I watched a series all day.', 'Assisti a uma série o dia todo.', '/aɪ wɑːtʃt ə ˈsɪriːz ɔːl deɪ/', '"Series" é igual no singular e no plural.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"watched","pos":"verb","ipa":"/wɑːtʃt/","gloss":"assistiu"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"series","pos":"noun","ipa":"/ˈsɪriːz/","gloss":"série"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-05', 'lesson-routine-a2-05', 5, 'sentence', 'We had a barbecue with friends.', 'Fizemos um churrasco com amigos.', '/wiː hæd ə ˈbɑːrbɪkjuː wɪð frɛndz/', '"Have a barbecue" = fazer churrasco.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"barbecue","pos":"noun","ipa":"/ˈbɑːrbɪkjuː/","gloss":"churrasco"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-06', 'lesson-routine-a2-05', 6, 'sentence', 'I didn''t do much.', 'Não fiz muita coisa.', '/aɪ ˈdɪdənt duː mʌtʃ/', 'Negativa no passado: "didn''t" + verbo base.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-07', 'lesson-routine-a2-05', 7, 'sentence', 'It rained the whole weekend.', 'Choveu o fim de semana inteiro.', '/ɪt reɪnd ðə hoʊl ˈwiːkɛnd/', '"The whole" = inteiro.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"rained","pos":"verb","ipa":"/reɪnd/","gloss":"choveu"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"whole","pos":"adjective","ipa":"/hoʊl/","gloss":"inteiro"},{"surface":"weekend","pos":"noun","ipa":"/ˈwiːkɛnd/","gloss":"fim de semana"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-08', 'lesson-routine-a2-05', 8, 'sentence', 'We slept in on Sunday.', 'Dormimos até tarde no domingo.', '/wiː slɛpt ɪn ɑːn ˈsʌndeɪ/', '"Sleep in" = dormir até tarde. Passado irregular: "slept".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"slept","pos":"verb","ipa":"/slɛpt/","gloss":"dormiu"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Sunday","pos":"proper noun","ipa":"/ˈsʌndeɪ/","gloss":"domingo"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-09', 'lesson-routine-a2-05', 9, 'sentence', 'Did you have fun?', 'Você se divertiu?', '/dɪd juː hæv fʌn/', '"Have fun" = divertir-se.', '[]'::jsonb, '[{"surface":"Did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"fun","pos":"noun","ipa":"/fʌn/","gloss":"diversão"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-05-10', 'lesson-routine-a2-05', 10, 'sentence', 'It went by so fast.', 'Passou muito rápido.', '/ɪt wɛnt baɪ soʊ fæst/', '"Go by" = passar (tempo). Passado: "went by".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"went","pos":"verb","ipa":"/wɛnt/","gloss":"foi (passado de go)"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"fast","pos":"adverb","ipa":"/fæst/","gloss":"rápido"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-routine-a2-06-01', 'lesson-routine-a2-06', 1, 'sentence', 'I''m going to visit my grandmother on Sunday.', 'Vou visitar minha avó no domingo.', '/aɪm ˈɡoʊɪŋ tuː ˈvɪzɪt maɪ ˈɡrænmʌðər ɑːn ˈsʌndeɪ/', '"Going to" + verbo = plano já decidido.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"visit","pos":"noun","ipa":"/ˈvɪzɪt/","gloss":"visita"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"grandmother","pos":"noun","ipa":"/ˈɡrænmʌðər/","gloss":"avó"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Sunday","pos":"proper noun","ipa":"/ˈsʌndeɪ/","gloss":"domingo"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-06-02', 'lesson-routine-a2-06', 2, 'sentence', 'What are you going to do tonight?', 'O que você vai fazer hoje à noite?', '/wʌt ɑːr juː ˈɡoʊɪŋ tuː duː təˈnaɪt/', 'Pergunta com "going to": "are you going to…".', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-06-03', 'lesson-routine-a2-06', 3, 'sentence', 'We''re not going to travel this year.', 'Não vamos viajar este ano.', '/wɪr nɑːt ˈɡoʊɪŋ tuː ˈtrævəl ðɪs jɪr/', 'Negativa: "not going to".', '[]'::jsonb, '[{"surface":"We''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"travel","pos":"verb","ipa":"/ˈtrævəl/","gloss":"viajar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-06-04', 'lesson-routine-a2-06', 4, 'sentence', 'It''s going to rain.', 'Vai chover.', '/ɪts ˈɡoʊɪŋ tuː reɪn/', '"Going to" também é previsão com evidência (céu escuro).', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-06-05', 'lesson-routine-a2-06', 5, 'sentence', 'I''m meeting Ana at five.', 'Vou encontrar a Ana às cinco.', '/aɪm ˈmiːtɪŋ ˈænə æt faɪv/', 'Presente contínuo para compromisso marcado.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"Ana","pos":"proper noun","ipa":"/ˈænə/","gloss":"Ana"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-06-06', 'lesson-routine-a2-06', 6, 'sentence', 'I''m free on Thursday.', 'Estou livre na quinta.', '/aɪm friː ɑːn ˈθɜːrzdeɪ/', '"Free" = disponível.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Thursday","pos":"proper noun","ipa":"/ˈθɜːrzdeɪ/","gloss":"quinta-feira"}]'::jsonb, NULL, NULL),
  ('unit-routine-a2-06-07', 'lesson-routine-a2-06', 7, 'sentence', 'I''m busy until noon.', 'Estou ocupado até o meio-dia.', '/aɪm ˈbɪzi ənˈtɪl nuːn/', '"Until" = até (tempo).', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"busy","pos":"adjective","ipa":"/ˈbɪzi/","gloss":"ocupado"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
